Object.Field:
if (#V0 < <%=odiRef.getOption( "COMPATIBLE" )%>) {
  throw new OdiKMException("ODIKM-ORA-10000", "ODIKM-ORA-10000: You are using RDBMS version #V0.#V1. This version does not support IKM COMPATIBLE=<%=odiRef.getOption( "COMPATIBLE" )%>.")
}

/* DETECTION_STRATEGY = <%=odiRef.getOption ("DETECTION_STRATEGY")%> */ <% /* for NONE strategy */ if ("NONE".equals( odiRef.getOption ("DETECTION_STRATEGY") )) { %> /* Command skiped due to chosen DETECTION_STRATEGY */ <% } else { %>
update <%=odiRef.getTable("L", "INT_NAME", "W")%> set IND_UPDATE = 'U' where (<%=odiRef.getColList("","[COL_NAME]", ", ", "", "UK")%>) in ( select <%=odiRef.getColList("","[COL_NAME]", ",\n\t\t\t", "", "UK")%> from <%=odiRef.getTable("L", "TARG_NAME", "A")%> )
<% }; %>

/* DETECTION_STRATEGY = <%=odiRef.getOption ("DETECTION_STRATEGY")%> */ <% /* for POST_FLOW strategy */ if ("POST_FLOW".equals( odiRef.getOption ("DETECTION_STRATEGY") ) && odiRef.getColList("","A", "", "", "((UPD and !TRG) and !UK)").length()>0) { %>
update <%=odiRef.getTable("L", "INT_NAME", "A")%> S set IND_UPDATE = 'N' where exists ( select 'X' from <%=odiRef.getTable("L", "TARG_NAME", "A")%> T where <%=odiRef.getColList("","T.[COL_NAME]\t= S.[COL_NAME]", "\n\tand\t", "", "UK")%> <%=odiRef.getColList("\tand\t","((T.[COL_NAME] = S.[COL_NAME]) or (T.[COL_NAME] IS NULL and S.[COL_NAME] IS NULL))", "\nand\t", "", "((UPD and !TRG) and !UK)")%> )
<% } else { %> /* Command skiped due to chosen DETECTION_STRATEGY */ <% }; %>

// Validating KM options

{# INCLUDE = 'ValidateOracleCompatible' #}

<%
/* Validate DETECTION_STRATEGY */
if (!(
	"MINUS".equals( odiRef.getOption ("DETECTION_STRATEGY") ) ||
	"NOT_EXISTS".equals( odiRef.getOption ("DETECTION_STRATEGY") ) ||
	"POST_FLOW".equals( odiRef.getOption ("DETECTION_STRATEGY") ) ||
	"NONE".equals( odiRef.getOption ("DETECTION_STRATEGY") )
))  {%>
throw new OdiKMException("ODIKM-STDKM-10000", "ODIKM-STDKM-10000: Invalid value \"<%=odiRef.getOption ("DETECTION_STRATEGY")%>\" for option \"DETECTION_STRATEGY\"")
<%};%>
